def apply_jac_tax(quote: dict, tax_rate_bps: int) -> dict:
    net = int(quote['net_cents'])
    tax = (net * int(tax_rate_bps)) // 10000
    gross = net + tax
    return {
        'net_cents': net,
        'tax_cents': tax,
        'gross_cents': gross,
        'tax_state_s2': 0,
    }

